443	
444	  describe('a resumed wishlist-move waits for merge-then-cap to settle (pass criterion 4)', () => {
445	    // Controlled-timing proof, per this step's own required approach: hold the "settle" signal
446	    // open, confirm isGuest has not yet flipped to false (so ZimmCartItemActions/
447	    // usePendingWishlistItem's own [isGuest]-keyed resume effect cannot have fired), then let it
448	    // settle and confirm isGuest does flip. Spies directly on the real QueryClient's own
449	    // isMutating() method — cartDrawerContainer's own gating effect reads this live, not the
450	    // reactive useIsMutating() value, specifically to avoid a stale-closure read; asserting via
451	    // the same live signal proves the mechanism actually used, not a stand-in for it.
452	    //
453	    // DISCLOSED LIMITATION, mutation-tested directly (not assumed): this test does NOT
454	    // distinguish cartDrawerContainer.tsx's use of a `useRef` (hasPendingPostAuthSettleRef) from
455	    // a plain `useState` for the "auth just succeeded" flag — swapping the ref for state and
456	    // re-running this exact suite leaves it green. The reason the ref is still required in the
457	    // real app is a same-commit React effect-ordering argument this test's own structure cannot
458	    // reproduce: it mocks useWishlistAuthDrawer entirely and invokes the captured onAuthSuccess
459	    // callback directly from test code, as a plain synchronous function call, followed by an
460	    // explicit, separate rerender() — never as a second real internal effect racing this
461	    // container's own gating effect within one commit. In the real (unmocked) app,
462	    // useWishlistAuthDrawer's own [isRegistered] effect and this container's gating effect both
463	    // live on the same fiber and both fire in the same commit when isRegistered flips (source
464	    // order: useWishlistAuthDrawer is called first, so its effect runs first) — a `setState`
465	    // queued from inside the first effect is not visible to the second effect's own closure until
466	    // a LATER render, whereas a ref mutation is visible immediately within that same flush. This
467	    // is the same class of stale-value trap useCartMergeAndCap.ts's own docblock documents fixing
468	    // via a live queryClient.isMutating() read instead of a closed-over hook value — reasoned
469	    // directly from React's own documented effect-scheduling behaviour, not verified by an
470	    // automated test here. The real proof for the ref-vs-state half is that reasoning, cited as
471	    // such, not this test.
472	    test('isGuest stays true after auth-success while mutations are in flight, and flips to false only once they drain', async () => {
473	      mockUseCustomerType.mockReturnValue({ isRegistered: false });
474	      let capturedOnAuthSuccess: (() => void) | undefined;
475	      mockUseWishlistAuthDrawer.mockImplementation(({ onAuthSuccess }: { onAuthSuccess?: () => void }) => {
476	        capturedOnAuthSuccess = onAuthSuccess;
477	        return buildWishlistAuthDrawerReturn();
478	      });
479	
480	      let isMutatingSpyValue = 0;
481	      const queryClient = new QueryClient({ defaultOptions: { queries: { retry: false } } });
482	      vi.spyOn(queryClient, 'isMutating').mockImplementation(() => isMutatingSpyValue);
483	
484	      const { rerender } = render(
485	        <QueryClientProvider client={queryClient}>
486	          <ChakraProvider theme={theme}>
487	            <CartDrawerContainer isOpen={true} onClose={vi.fn()} />
488	          </ChakraProvider>
489	        </QueryClientProvider>,
490	      );
491	
492	      expect(screen.getByTestId('mock-cart-item-actions-product-a')).toHaveAttribute('data-is-guest', 'true');
493	
494	      // Simulate useWishlistAuthDrawer's own real effect: isRegistered flips true and, in the
495	      // same synchronous body, calls onAuthSuccess before its own mergeBasket.mutate(...) — here
496	      // represented by isMutatingSpyValue already being non-zero by the time onAuthSuccess fires.
497	      isMutatingSpyValue = 1;
498	      mockUseCustomerType.mockReturnValue({ isRegistered: true });
499	      capturedOnAuthSuccess?.();
500	      rerender(
501	        <QueryClientProvider client={queryClient}>
502	          <ChakraProvider theme={theme}>
503	            <CartDrawerContainer isOpen={true} onClose={vi.fn()} />
504	          </ChakraProvider>
505	        </QueryClientProvider>,
506	      );
507	
508	      // Still guest while the merge/cap chain (represented by the live isMutating spy) is in
509	      // flight — the resume must not have fired yet.
510	      expect(screen.getByTestId('mock-cart-item-actions-product-a')).toHaveAttribute('data-is-guest', 'true');
511	
512	      // Settle: mutation count drains to 0.
513	      isMutatingSpyValue = 0;
514	      rerender(
515	        <QueryClientProvider client={queryClient}>
516	          <ChakraProvider theme={theme}>
517	            <CartDrawerContainer isOpen={true} onClose={vi.fn()} />
518	          </ChakraProvider>
519	        </QueryClientProvider>,
520	      );
521	
522	      await waitFor(() =>
523	        expect(screen.getByTestId('mock-cart-item-actions-product-a')).toHaveAttribute('data-is-guest', 'false'),
524	      );
525	    });
526	
527	    test('steady state — a shopper already registered when this container mounts is never treated as a waiting guest', () => {
528	      mockUseCustomerType.mockReturnValue({ isRegistered: true });
529	      renderContainer();
530	      expect(screen.getByTestId('mock-cart-item-actions-product-a')).toHaveAttribute('data-is-guest', 'false');
531	    });
532	  });
533	
534	  describe('empty basket renders ZimmCartEmptyState, not an empty children array (pass criterion 5)', () => {
535	    test('zero items: renders ZimmCartEmptyState, no ProductItem, inside the real ZimmCartDrawer', async () => {
536	      currentBasket = buildBasket([]);
537	      renderContainer();
538	      expect(await screen.findByRole('dialog', { name: 'YOUR BAG IS EMPTY' })).toBeInTheDocument();
539	      expect(screen.getByTestId('mock-empty-state')).toBeInTheDocument();
540	      expect(screen.queryByTestId(/mock-product-item-/)).not.toBeInTheDocument();
541	    });
542	
543	    test('non-zero items: renders the real mapped item list, not ZimmCartEmptyState', async () => {
544	      renderContainer();
545	      expect(await screen.findByRole('dialog', { name: 'BAG • 2' })).toBeInTheDocument();
546	      expect(screen.queryByTestId('mock-empty-state')).not.toBeInTheDocument();
547	      expect(screen.getByTestId('mock-product-item-item-a')).toBeInTheDocument();
548	      expect(screen.getByTestId('mock-product-item-item-b')).toBeInTheDocument();
549	    });
550	  });
551	
552	  describe('footer renders ZimmCartButtonGroup; messages slot is genuinely omitted (pass criterion 6)', () => {
553	    test('footer slot renders ZimmCartButtonGroup', async () => {
554	      renderContainer();
555	      expect(await screen.findByTestId('mock-button-group')).toBeInTheDocument();
556	    });
557	
558	    test('the messages slot band renders with no content — real ZimmCartDrawer, no messages prop reaches it', async () => {
559	      renderContainer();
560	      // ZimmCartDrawer always renders its own messages band regardless (height-reserving, per its
561	      // own recipe — `<chakra.div __css={styles.messages}>{messages}</chakra.div>`) — asserting the
562	      // whole dialog carries none of this container's own rendered text/testids in that band is as
563	      // far as a RENDERED assertion can honestly go here. It cannot, by itself, distinguish
564	      // "omitted" from "explicitly passed messages={undefined}" — both produce byte-identical
565	      // output, since {undefined} renders nothing either way. The "genuinely omitted, not
566	      // attempted" half of this pass criterion is a static fact about this container's own JSX,
567	      // verified directly by inspection, not by this test: `grep -n "messages" cartDrawerContainer.tsx`
568	      // returns zero matches — the prop is never referenced anywhere in this file, not merely
569	      // passed a falsy value.
570	      expect(await screen.findByRole('dialog')).toBeInTheDocument();
571	    });
572	  });
573	
574	  describe('this container owns no isOpen/onClose state itself (pass criterion 7)', () => {
575	    test('isOpen is read straight from props — passing false renders the drawer closed', () => {
576	      renderContainer({ isOpen: false });
577	      expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
578	    });
579	
580	    test('onClose is forwarded verbatim to ZimmCartDrawer, not wrapped or replaced', async () => {
581	      const onClose = vi.fn();
582	      renderContainer({ onClose });
583	      await screen.findByRole('dialog');
584	      fireEvent.keyDown(screen.getByRole('dialog'), { key: 'Escape' });
585	      await waitFor(() => expect(onClose).toHaveBeenCalledTimes(1));
586	    });
587	  });
588	});
