import React from 'react'
import PropTypes from 'prop-types'

// Chakra Components
import {Stack} from '@salesforce/retail-react-app/app/components/shared/ui'

// Project Components
import ProductItem from '@salesforce/retail-react-app/app/components/product-item'

/**
 * Component that renders a list of product items with consistent props and behavior.
 * Extracted from cart page to be reusable across different contexts.
 */
const ProductItemList = ({
    productItems = [],
    renderSecondaryActions,
    renderDeliveryActions,
    onItemQuantityChange,
    onRemoveItemClick,
    // Optional props with defaults
    productsByItemId = {},
    isProductsLoading = false,
    localQuantity = {},
    localIsGiftItems = {},
    isCartItemLoading = false,
    selectedItem = null,
    removingItemIds = [],
    // Styling options
    hideBorder = false,
    hideBottomBorder = false,
    // Pickup information
    getShipmentInfoForProduct = null
}) => {
    return (
        <Stack spacing={4}>
            {productItems.map((productItem) => {
                const isBonusProductItem = productItem.bonusProductLineItem
                // Check if this product item (regular or bonus) is being removed
                const isBeingRemoved = removingItemIds.includes(productItem.itemId)

                // Get pickup information for this product item
                const shipmentInfo = getShipmentInfoForProduct
                    ? getShipmentInfoForProduct(productItem)
                    : null
                const pickupInStore = shipmentInfo?.isPickupOrder || false

                return (
                    <ProductItem
                        key={productItem.itemId}
                        isBonusProduct={isBonusProductItem}
                        isRemoving={isBeingRemoved}
                        pickupInStore={pickupInStore}
                        containerStyles={{
                            borderX: 'none',
                            borderTop: 'none',
                            boxShadow: 'none',
                            ...(hideBottomBorder && {borderBottom: 'none'})
                        }}
                        secondaryActions={
                            renderSecondaryActions
                                ? renderSecondaryActions({
                                      productItem,
                                      isAGift: localIsGiftItems[productItem.itemId]
                                          ? localIsGiftItems[productItem.itemId]
                                          : productItem.gift
                                  })
                                : null
                        }
                        deliveryActions={
                            renderDeliveryActions ? renderDeliveryActions(productItem) : null
                        }
                        product={{
                            ...productItem,
                            ...(productsByItemId && productsByItemId[productItem.itemId]),
                            isProductUnavailable: !isProductsLoading
                                ? !productsByItemId?.[productItem.itemId]
                                : undefined,
                            price: productItem.price,
                            quantity: localQuantity[productItem.itemId]
                                ? localQuantity[productItem.itemId]
                                : productItem.quantity
                        }}
                        onItemQuantityChange={onItemQuantityChange?.bind(this, productItem)}
                        showLoading={
                            (isCartItemLoading && selectedItem?.itemId === productItem.itemId) ||
                            isBeingRemoved
                        }
                        handleRemoveItem={onRemoveItemClick}
                        hideBorder={hideBorder}
                    />
                )
            })}
        </Stack>
    )
}

ProductItemList.propTypes = {
    productItems: PropTypes.arrayOf(PropTypes.object),
    renderSecondaryActions: PropTypes.func,
    renderDeliveryActions: PropTypes.func,
    onItemQuantityChange: PropTypes.func.isRequired,
    onRemoveItemClick: PropTypes.func,
    productsByItemId: PropTypes.object,
    isProductsLoading: PropTypes.bool,
    localQuantity: PropTypes.object,
    localIsGiftItems: PropTypes.object,
    isCartItemLoading: PropTypes.bool,
    selectedItem: PropTypes.object,
    removingItemIds: PropTypes.arrayOf(PropTypes.string),
    hideBorder: PropTypes.bool,
    hideBottomBorder: PropTypes.bool,
    getShipmentInfoForProduct: PropTypes.func
}

export default ProductItemList

import type { ShopperBasketsTypes, ShopperProductsTypes } from 'commerce-sdk-isomorphic';
import { findImageGroupBy } from '@salesforce/retail-react-app/app/utils/image-groups-utils';
import { getDisplayVariationValues } from '@salesforce/retail-react-app/app/utils/product-utils';

/*
 * Converts an SDK basket `productItem` into a self-contained display-data shape, mirroring the
 * `productListCardMapper.ts` precedent (`overrides/app/pages/product-list/productListCardMapper.ts`,
 * PR #85) for how a page-scoped SDK-to-props mapper is organised in this codebase: exported
 * "select"-prefixed functions (that file exports three: `selectGalleryImages`,
 * `selectSizeChipValues`, `selectProductListCard` - corrected here, an earlier draft of this
 * comment said "a single" one, which was wrong), an untyped-base-package input narrowed to a
 * local type, and a `.test.ts` asserting the mapped shape directly (see that file's own
 * `ProductListSearchHit`/`RawImage` pattern, mirrored below for `CartLineItem`/`CartItemImage`).
 *
 * Disclosed design choice, not a directly sourced requirement (flagged per this step's own
 * instructions): `ProductItem`/`ItemVariantProvider` (`overrides/app/components/product-item/
 * index.tsx:140`, `overrides/app/components/item-variant/index.tsx:43`) both currently declare
 * their real data-carrying prop as the raw untyped basket/product object itself
 * (`product`/`variant`, both `SfccProduct`/`SfccVariant = any`) — today's leaves read every
 * display field (image, name, combined attributes) directly off that object via
 * `useItemVariant()`, not from individually-mapped props. This mapper is, per this step's plan
 * text, "an as-yet-unused-by-anything-else container-layer function" — it does not change or
 * feed either of those two files (out of this step's scope). What it produces instead is a pure,
 * tested equivalent of the specific per-field computations those leaves and
 * `product-quantity-picker.tsx`/`use-derived-product.js` already perform internally off that same
 * raw object (image+alt, combined colour/size, quantity, stepQuantity) — ready for whichever
 * future step decides how a real page hands data down, without having modified any of those
 * existing files.
 *
 * `CartLineItem` models the REAL runtime shape a basket line item has by the time it reaches
 * those leaves: the un-overridden base cart page never passes the raw `basket.productItems[i]`
 * alone — it merges it with the matching full `Product` (fetched separately via `useProducts`)
 * before handing it down: `product={{...productItem, ...productsByItemId[productItem.itemId],
 * price: productItem.price, quantity: ...}}` (see
 * `node_modules/@salesforce/retail-react-app/app/components/product-item-list/index.jsx`, the
 * `<ProductItem product={...}>` call). `imageGroups`/`variationAttributes`/`variationValues`/
 * `stepQuantity`/`name` all come from that merged-in `Product` half, not from
 * `ShopperBasketsTypes.ProductItem` itself (confirmed against its generated fields — it has no
 * image/variation/stepQuantity fields at all beyond its own `{[key: string]: any}` catch-all).
 *
 * Both halves are `Pick`'d, not intersected raw (zm-tester, SFCC-11 step 3.4 finding): the real
 * generated `ProductItem` type carries the identical `{[key: string]: any}` catch-all the comment
 * above already calls out on `Product`. Intersecting it raw would silently resolve a typo'd field
 * name (or a nonexistent one) to `any` instead of a compile error — empirically confirmed harmless
 * today (every real access below is spelled correctly) but a real, latent gap a future edit could
 * hit silently. `Pick`ing both halves closes it the same way on both sides.
 */
type CartLineItem = Pick<ShopperBasketsTypes.ProductItem, 'itemId' | 'productId' | 'quantity' | 'productName'> &
  Pick<
    ShopperProductsTypes.Product,
    'imageGroups' | 'variationAttributes' | 'variationValues' | 'stepQuantity' | 'name'
  >;

type CartItemImage = {
  src?: string;
  /**
   * Always a string, never undefined — even when there's no image at all (falls back to the
   * item's own name, then `''`). See `selectCartItemImage`'s own doc comment for the fallback
   * chain and why this differs from `productListCardMapper.ts`'s `toCardImage`, which returns
   * `undefined` for the whole image on a miss instead.
   */
  alt: string;
};

type CartItemMapperResult = {
  itemId?: string;
  productId?: string;
  name: string;
  image: CartItemImage;
  combinedAttributes: string;
  quantity?: number;
  stepQuantity: number;
};

/**
 * Matches `node_modules/@salesforce/retail-react-app/app/hooks/use-derived-product.js:38`'s own
 * `product?.stepQuantity || 1` exactly — reused as a value, not a shared import, since that hook
 * itself isn't a pure function this module can call (it's stateful, `useState`-backed).
 */
const DEFAULT_STEP_QUANTITY = 1;

/**
 * Selects this line item's display image, always returning a defined `alt` even when there is no
 * image at all (unlike `productListCardMapper.ts`'s `toCardImage`, which returns `undefined` for
 * the whole image on a miss — a PLP card can legitimately skip rendering entirely when it has
 * nothing to show; a cart line item cannot, per this step's own pass criteria).
 *
 * The lookup itself reuses `findImageGroupBy` exactly as
 * `overrides/app/components/item-variant/item-image.tsx:70-73` already does (same `viewType:
 * 'small'` / `selectedVariationAttributes` call) rather than reimplementing image-group matching.
 */
const selectCartItemImage = (item: CartLineItem): CartItemImage => {
  const image = findImageGroupBy(item.imageGroups, {
    viewType: 'small',
    selectedVariationAttributes: item.variationValues,
  })?.images?.[0];

  return {
    src: image?.disBaseLink || image?.link,
    alt: image?.alt || item.productName || item.name || '',
  };
};

/**
 * Combines the colour and size variation values into the single string the Figma cart-item spec
 * calls for, reusing the exact mechanism
 * `overrides/app/components/item-variant/item-attributes.tsx:98,148-150` already uses for its own
 * `combineAttributeValues` behaviour (`getDisplayVariationValues(...)` then
 * `Object.values(...).join(', ')`) rather than reimplementing string-combining from scratch.
 *
 * Ordering is inherited from that same call, not independently re-sorted here: it reflects
 * whichever order the incoming `variationValues` object's own keys are in (see
 * `getDisplayVariationValues`'s `Object.entries(values).reduce(...)`,
 * `node_modules/@salesforce/retail-react-app/app/utils/product-utils.js:30`). This is the
 * identical mechanism `item-attributes.tsx`'s own docblock (line 31) already cites as producing
 * "Lilac Sand, One size" (colour, size) for real Zimmermann catalog data —
 * `product-item/index.tsx`'s docblock (line 44) corroborates the same combined-string behaviour
 * generically ("colour, size") without repeating that specific example. This function inherits
 * that already-verified behaviour rather than re-guaranteeing the order independently.
 */
const selectCombinedAttributes = (item: CartLineItem): string => {
  const variationValues = getDisplayVariationValues(item.variationAttributes, item.variationValues);
  return variationValues ? Object.values(variationValues).join(', ') : '';
};

/**
 * Maps one basket line item (already merged with its full product data — see this file's own
 * module docblock) to a plain display-data shape: image, name, one combined colour/size string,
 * and quantity/stepQuantity passed through. Pure function, no hooks — keeps every consumer in B3
 * prop-driven with no data-fetching hook in a leaf, per this step's own plan text.
 */
export const selectCartItemProps = (item: CartLineItem): CartItemMapperResult => ({
  itemId: item.itemId,
  productId: item.productId,
  name: item.productName || item.name || '',
  image: selectCartItemImage(item),
  combinedAttributes: selectCombinedAttributes(item),
  quantity: item.quantity,
  stepQuantity: item.stepQuantity || DEFAULT_STEP_QUANTITY,
});

import { useQueryClient } from '@tanstack/react-query';
import type { ShopperBasketsV2Types } from 'commerce-sdk-isomorphic';
import { useShopperBasketsV2Mutation as useShopperBasketsMutation } from '@salesforce/commerce-sdk-react';
import { getMaxOrderQuantity } from 'app/utils/maxOrderQuantity';

/**
 * The minimal basket shape this hook needs, regardless of which caller supplies it: the
 * post-auth callback (`useWishlistAuthDrawer.ts`, wired in this step) passes the resolved value
 * of its own `mergeBasket` mutation directly; the cart drawer's render guard
 * (`overrides/app/pages/cart/cartDrawerContainer.tsx`, step 4.6 — not yet built) will pass its
 * own `useCurrentBasket()` data. `Pick`-narrowed, matching `cartItemMapper.ts`'s own established
 * pattern for taking an untyped-at-the-edges SDK response and narrowing it to only the fields a
 * pure function actually reads, rather than depending on the exact generic SDK response type
 * either caller's own mutation/query hook happens to produce.
 */
export type CartCapBasket = Pick<ShopperBasketsV2Types.Basket, 'basketId' | 'lastModified' | 'productItems'>;

/**
 * Outcome of one `capBasketQuantities` call. A discriminated union (typescript.md's guidance for
 * variant/state modelling) rather than a boolean-plus-optional-error: each branch is something a
 * caller could reasonably want to react to differently, and no AC or copy exists yet for any of
 * them (that is `useCartMessages`, step 4.3, not built) — this file only reports what happened,
 * it does not decide what the shopper sees.
 */
export type CartCapResult =
  | { status: 'not-needed' }
  | { status: 'skipped'; reason: 'mutation-in-flight' | 'already-attempted-this-version' }
  | { status: 'corrected' }
  | { status: 'error'; error: unknown };

/**
 * `getMaxOrderQuantity` is typed for a SCAPI product response (`id: string` required — see
 * `overrides/app/utils/maxOrderQuantity.ts`). A basket line item has no `id` field at all: only
 * `itemId`/`productId` (confirmed against the generated `BasketProductItem` type — verified via
 * a throwaway `tsc` repro that assigning a same-shaped object to a type requiring `id` fails
 * with "Property 'id' is missing"), so passing one directly does not type-check, despite it
 * carrying the same `{[key: string]: any}` catch-all a real `c_maxOrderQuantity` value would
 * arrive through once SFCC-268 ships. `product-item/index.tsx` already lives with the identical
 * gap at its own `getMaxOrderQuantity(product)` call site (`type SfccProduct = any`, lines 171
 * and 331) — narrowed here with an explicit, commented cast instead of a bare `any` parameter,
 * per typescript.md's "no `any` without an inline comment" rule.
 */
const getLineMaxOrderQuantity = (item: ShopperBasketsV2Types.BasketProductItem): number =>
  getMaxOrderQuantity(item as unknown as Parameters<typeof getMaxOrderQuantity>[0]);

/**
 * A line needs correction once its quantity exceeds the cap — i.e. once it reaches the smallest
 * over-cap value (`max + 1`; `4` when `max` is `3`) or anything above it. Written as `quantity >
 * max` rather than comparing against a separately-named `max + 1` boundary, but the two are the
 * same comparison: this must be a "the whole range above the boundary" check, not an
 * exact-equality check against a single value — an equality check against `max + 1` alone would
 * correctly catch a line at 4 but wrongly leave a line at 5 or more uncorrected, which is
 * observably wrong against this hook's own test fixture (a line at 5 must reduce to 3, not stay
 * at 5).
 */
const needsQuantityCorrection = (
  item: ShopperBasketsV2Types.BasketProductItem,
): item is ShopperBasketsV2Types.BasketProductItem & { quantity: number } =>
  typeof item.quantity === 'number' && item.quantity > getLineMaxOrderQuantity(item);

/**
 * SFCC baskets carry no explicit version counter. `basketId` + `lastModified` change together on
 * every write SFCC accepts (both real fields on the generated `Basket` type), so the pair is a
 * workable proxy for "the exact basket state a correction was last attempted against" — this is
 * this file's own reasoned choice, not sourced from an existing codebase precedent or doc.
 */
const getBasketVersionKey = (basket: CartCapBasket): string => `${basket.basketId ?? ''}:${basket.lastModified ?? ''}`;

/**
 * Storage key for "which basket version has a correction already been attempted against."
 * Deliberately not a `useRef` — the post-auth callback (`useWishlistAuthDrawer.ts`) and the
 * future render guard (step 4.6) each get their own separate `useCartMergeAndCap()` call, and
 * therefore their own separate refs, since they mount in two different React component trees. A
 * plain ref cannot coordinate between them. Piggybacking on the already-global `QueryClient` (the
 * same one `capBasketQuantities`'s own mutation-in-flight guard reads from — see that function's
 * own comment) via `getQueryData`/`setQueryData` gives real cross-instance-shared storage without
 * inventing a new module-level singleton or Context provider. It is also, unlike a React-render-
 * time hook value, live/imperative — reading and then
 * immediately writing it inside `capBasketQuantities` with no `await` in between (see that
 * function) leaves no window for two near-simultaneous calls to both pass the check before either
 * has recorded its attempt, since JavaScript runs that synchronous read-then-write as one
 * uninterruptible step.
 */
const CAP_ATTEMPT_QUERY_KEY = ['zimmCartMergeAndCap', 'attemptedBasketVersion'] as const;

export type UseCartMergeAndCapReturn = {
  /**
   * Checks every basket line against `getMaxOrderQuantity` and, if any line exceeds its cap,
   * issues one `updateItemsInBasket` write reducing every over-cap line to its own max in a
   * single request (matching the SFCC-11 plan's "one write" framing even when more than one line
   * needs correcting). Resolves only once that write — if one was issued — has fully settled, so
   * a caller sequencing merge -> cap -> a future wishlist-resume can `await` this in turn without
   * racing it.
   */
  capBasketQuantities: (basket: CartCapBasket) => Promise<CartCapResult>;
};

/**
 * Hook — the shared "cap" half of SFCC-250's merge-then-cap flow. Two callers share this one
 * implementation, not two copies: the post-auth callback inside `useWishlistAuthDrawer.ts`'s own
 * `isRegistered` effect (wired in this step, right after that effect's existing `mergeBasket`
 * call), and the cart drawer's render guard, which will live in
 * `overrides/app/pages/cart/cartDrawerContainer.tsx` (not yet built — a later step, 4.6, wires
 * that second call site; this hook is written to support it, not to assume it already exists).
 *
 * Per rules-of-hooks, call this at the top level of whichever hook or component needs it — never
 * from inside a `useEffect` callback — and invoke the returned `capBasketQuantities` function
 * itself from inside the effect/render path instead.
 *
 * @returns `capBasketQuantities`, the one function both callers invoke.
 */
export const useCartMergeAndCap = (): UseCartMergeAndCapReturn => {
  const queryClient = useQueryClient();
  const updateItemsInBasket = useShopperBasketsMutation('updateItemsInBasket');

  const capBasketQuantities = async (basket: CartCapBasket): Promise<CartCapResult> => {
    // No-op while any mutation is in flight (this hook's own prior correction, the merge that
    // just ran, a shopper's manual quantity edit — anything) so this can never race a write
    // already under way. See this function's own JSDoc.
    //
    // REWORK (round 1, Tester-confirmed defect): this must be a LIVE read taken at the moment
    // this function actually runs — not a React-render-time value closed over at this hook's own
    // top level. `capBasketQuantities` is captured once by its caller and invoked later, from
    // inside an async callback (`useWishlistAuthDrawer.ts`'s `mergeBasket.mutate(...).onSuccess`,
    // itself only reachable after a real network round trip) with no guarantee that hook instance
    // re-renders in between. A `useIsMutating()` value read at this hook's own top level (the
    // original approach here) would still reflect whatever mutation count existed at that earlier
    // render, not the real state at the moment this guard actually needs to check it.
    //
    // `queryClient.isMutating(filters?)` (confirmed against the installed
    // `@tanstack/query-core@4.43.0` source — a single deduped version across this project's whole
    // dependency tree, per `npm ls @tanstack/react-query` — `node_modules/@tanstack/query-core/
    // build/lib/queryClient.esm.js`: `isMutating(filters) { return this.mutationCache.findAll(
    // {...filters, fetching: true}).length; }`) computes this fresh from the live mutation cache
    // on every call. It is the exact same computation `useIsMutating()` itself wraps in
    // `useSyncExternalStore` for React reactivity (`node_modules/@tanstack/react-query/build/lib/
    // useIsMutating.esm.js`: `() => queryClient.isMutating(filters)`), just read directly instead
    // of through a render-synced subscription — so this preserves the exact same "every mutation
    // anywhere in the app" scope this guard has always had (commerce-sdk-react's basket mutation
    // hooks set no `mutationKey`, so an unscoped call is still the only reading that sees all of
    // them), it now just reads that scope live instead of stale.
    if (queryClient.isMutating() > 0) {
      return { status: 'skipped', reason: 'mutation-in-flight' };
    }

    const correctedItems = (basket.productItems ?? []).filter(needsQuantityCorrection).map((item) => ({
      itemId: item.itemId,
      productId: item.productId,
      quantity: getLineMaxOrderQuantity(item),
    }));

    if (correctedItems.length === 0) {
      return { status: 'not-needed' };
    }

    if (!basket.basketId) {
      // No basketId means there is nothing valid to address a write at — surface this as an
      // error rather than silently doing nothing, so a caller can tell "nothing needed fixing"
      // apart from "something needed fixing and couldn't be".
      return { status: 'error', error: new Error('useCartMergeAndCap: basket is missing a basketId.') };
    }

    const versionKey = getBasketVersionKey(basket);
    if (queryClient.getQueryData<string>(CAP_ATTEMPT_QUERY_KEY) === versionKey) {
      // Loop guard: a correction has already been attempted against this exact basket state,
      // whether it succeeded or failed — do not retry it. See CAP_ATTEMPT_QUERY_KEY's own
      // comment for why this is a live cache read rather than a per-instance ref, and why
      // setting it below, before the `await`, is what keeps this race-free.
      return { status: 'skipped', reason: 'already-attempted-this-version' };
    }
    queryClient.setQueryData(CAP_ATTEMPT_QUERY_KEY, versionKey);

    try {
      await updateItemsInBasket.mutateAsync({
        parameters: { basketId: basket.basketId },
        body: correctedItems,
      });
      return { status: 'corrected' };
    } catch (error) {
      // Surfaced to the caller, not retried: the version is already marked attempted above, so a
      // later call against this same unchanged basket state returns 'skipped' rather than
      // hammering the server again — no retry storm.
      return { status: 'error', error };
    }
  };

  return { capBasketQuantities };
};

